// Generated by `python -m holdgen_server.codegen` from the pydantic models. Do not edit.

export interface BBox {
  min: [number, number, number];
  max: [number, number, number];
}

export interface BuildSettings {
  voxel?: number;
  smooth_sigma_vox?: number;
  sample_step?: number;
}

export interface BuildStatus {
  id: string;
  name: string;
  state: "queued" | "running" | "done" | "failed";
  created: string;
  finished?: string | null;
  error?: string | null;
  log?: string[];
  files?: string[];
  report?: Record<string, unknown> | null;
}

export interface Dent {
  type: "dent";
  /** With a 2D center: 'front' = [x, y], 'ledge' = [x, z]. */
  surface?: ("front" | "ledge") | null;
  center: number[];
  /** 1-sigma radii along x, y, z (mm). */
  size?: [number, number, number];
  /** mm; positive removes material, negative adds. */
  depth: number;
  note?: string;
}

export interface EndCaps {
  /** Rounded end used where no view extends past the outermost station. */
  radius?: number;
}

export interface ErrorResponse {
  error: string;
  issues?: Issue[];
}

export interface Extents {
  x: number[];
  y_lo: number[];
  y_hi: number[];
  z_hi: number[];
}

/** Loose guide seen from the front ([x, y]): the hold's upper and lower edge, each an open curve from the left tip to the right tip. The two edges share their end points (the tips). */
export interface FrontView {
  /** Upper edge [x, y], left tip to right tip. */
  upper: [number, number][];
  /** Lower edge [x, y], left tip to right tip. */
  lower: [number, number][];
  /** Influence between stations. Zero at every station regardless. */
  strength?: number;
}

export interface Groove {
  type: "groove";
  surface?: ("front" | "ledge") | null;
  path: number[][];
  width?: number;
  depth: number;
  note?: string;
}

export interface HoldList {
  holds: HoldSummary[];
}

export interface HoldSpec {
  schema?: "hold-spec/1";
  name: string;
  units?: "mm";
  wall_angle_deg?: number;
  description?: string;
  stations: Station[];
  front_view?: FrontView | null;
  top_view?: TopView | null;
  end_caps?: EndCaps;
  features?: (Dent | Groove)[];
  mounting?: Mounting;
  build?: BuildSettings;
  notes?: Note[];
}

export interface HoldSummary {
  name: string;
  updated: string;
  stations: number;
  description: string;
}

export interface Issue {
  level: "error" | "warning";
  code: string;
  message: string;
  path?: (string | number)[];
}

export interface LoftInfo {
  x_min: number;
  x_max: number;
  landmarks: string[];
  tips: Record<string, "taper" | "cap">;
}

export interface MeshPayload {
  /** base64 little-endian float32 xyz triples */
  positions: string;
  /** base64 little-endian uint32 triangle indices */
  indices: string;
  vertex_count: number;
  triangle_count: number;
}

export interface Mounting {
  /** Screw positions [x, y] on the wall. */
  screws?: [number, number][];
  hole_dia?: number;
  countersink_dia?: number;
}

export interface Note {
  anchor: NoteAnchor;
  text?: string;
}

export interface NoteAnchor {
  view: "front" | "top" | "section";
  at: [number, number];
  station_x?: number | null;
}

export interface PreviewRequest {
  spec: HoldSpec;
  /** Arc-length sample step of the preview loft (mm). */
  step?: number;
  /** Spacing of preview rings along x (mm). */
  dx?: number;
}

export interface PreviewResponse {
  issues: Issue[];
  loft: LoftInfo;
  extents: Extents;
  mesh: MeshPayload;
  bbox: BBox;
  readouts: ReadoutRow[];
  screws: ScrewFace[];
}

export interface ReadoutRow {
  x: number;
  kind: "station" | "between";
  readouts: Readouts;
}

export interface Readouts {
  depth: number;
  chord_incut: number;
  incut_at_wall: number | null;
  incut_near_lip: number | null;
  ledge_below_horizontal_on_wall: number;
  thickness: number;
  height: number;
}

export interface SaveResponse {
  name: string;
  issues: Issue[];
}

export interface ScrewFace {
  x: number;
  y: number;
  face_z: number;
}

export interface SectionAtRequest {
  spec: HoldSpec;
  x: number;
}

export interface SectionAtResponse {
  station: Station;
}

export interface SpecRequest {
  spec: HoldSpec;
}

/** A drawn cross-section. Authoritative: the built hold matches it within the voxel tolerance. */
export interface Station {
  /** Position along the hold (mm). */
  x: number;
  /** Control points [z, y]. First = bottom root on the wall, then up the face, over the lip, down the ledge; last = ledge root on the wall. */
  points: [number, number][];
  /** Landmark name -> point index. bottom_root/ledge_root are implicit. Same names, same order on every station. */
  landmarks?: Record<string, number>;
  /** Point indices where the spline has a sharp corner. */
  corners?: number[];
  note?: string;
}

/** Loose guide seen from above ([x, z]): an open curve from the wall at the left end, out over the hold, back to the wall at the right end. First and last points sit on the wall (z = 0). */
export interface TopView {
  points: [number, number][];
  /** Influence between stations. Zero at every station regardless. */
  strength?: number;
  corners?: number[];
}

export interface ValidateResponse {
  issues: Issue[];
}

export type Feature = Dent | Groove;
